PROMPTS = {
    "rag_assistant": {
        "v1": """
        Answer using the provided context.
        """,

        "v2": """
        Answer using the provided context.
        If the answer is unavailable,
        clearly state that.
        Include relevant source references.
        """
    }
}

def get_prompt(name, version):

    try:
        return PROMPTS[name][version]
    except KeyError:
        raise ValueError(
            "Prompt or version not found"
        )

prompt = get_prompt(
    "rag_assistant",
    "v2"
)

print(prompt)
